// apps/backend/src/modules/ai/ai.service.ts
  async ask(question: string, run: (queries: any[]) => Promise<any[]>, who: { role?: string } = {}, history: { q: string; a: string }[] = []) {
    const q = String(question || '').trim().slice(0, 500);
    if (!q) throw new BadRequestException('Escribí tu pregunta.');
    // La IA con herramientas (en la nube, sobre lo que sincronizó la caja). Si la nube todavía
    // no tiene datos de este comercio, sigue como antes: consultas fijas corridas en esta PC.
    try {
      const { result, left, leftToday, limits } = await this.call('agent', {
        question: q, channel: 'app', role: who.role === 'SUPERVISOR' ? 'SUPERVISOR' : 'ADMIN',
        history: (history || []).slice(-2).map((h) => ({ q: String(h?.q || '').slice(0, 300), a: String(h?.a || '').slice(0, 1200) })),
      });
      return { answer: String(result?.answer || ''), left, questionsLeftToday: leftToday, limits };
    } catch (err: any) {
      if (!err?.noCloudData) throw err;
    }
    const { result: plan } = await this.call('ask', { step: 'plan', question: q });
    const queries = Array.isArray(plan?.queries) ? plan.queries : [];
    if (!queries.length) return { answer: String(plan?.noSePuede || 'Eso no lo puedo responder con los datos del sistema.'), data: [] };
    const data = await run(queries);
    const { result, left, leftToday } = await this.call('ask', { step: 'answer', question: q, data });
    return { answer: String(result?.answer || ''), data, left, questionsLeftToday: leftToday };
  }

// apps/backend/src/modules/ai/insights.service.ts

  async run(queries: AskQuery[]) {
    const out: any[] = [];
    for (const q of (queries || []).slice(0, 3)) {
      try {
        out.push({ consulta: q.tipo, ...(await this.one(q)) });
      } catch (err: any) {
        out.push({ consulta: q.tipo, error: 'No se pudo calcular' });
      }
    }
    return out;
  }

