      const userPayload = {
        name: payload.name || payload.given_name || email.split('@')[0],
        email: email,
        picture: payload.picture || ''
      };
      this.googleAuthService.setLinkedGoogleUser(userPayload);
      return { success: true, user: userPayload };
    } catch (err: any) {
      throw new BadRequestException('Error al verificar el token de Google: ' + err.message);
    }
  }

// apps/backend/src/modules/auth/google-auth.service.ts

  public verifyToken(idToken: string): Promise<any> {
    return new Promise((resolve, reject) => {
      const url = `https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(idToken)}`;
      https.get(url, (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          try {
            const parsed = JSON.parse(data);
            if (parsed.error_description || parsed.error) {
              reject(new Error(parsed.error_description || parsed.error));
            } else {
              resolve(parsed);
            }
          } catch (e) {
            reject(e);
          }
        });
      }).on('error', (err) => {
        reject(err);
      });
    });
  }

