model Sale {
  id                   String   @id @default(uuid())
  saleNumber           Int      @unique @map("sale_number")
  userId               String   @map("user_id")
  sessionId            String   @map("session_id")
  subtotal             Float
  taxAmount            Float    @default(0) @map("tax_amount")
  discountAmount       Float    @default(0) @map("discount_amount")
  total                Float
  paymentMethodSummary String   @map("payment_method_summary") // CASH | CLOVER | MERCADOPAGO | MIXED
  status               String   @default("COMPLETED") // COMPLETED | CANCELLED | REFUNDED
  notes                String?
  clientId             String?  @map("client_id")
  pickedUpBy           String?  @map("picked_up_by")
  isAcopio             Boolean  @default(false) @map("is_acopio")
  acopioStatus         String   @default("NONE") @map("acopio_status") // NONE | PENDING | PARTIAL | COMPLETED
  createdAt            DateTime @default(now()) @map("created_at")

  // ---- Facturación electrónica (ARCA): columnas de la 1.0.21 a la 1.0.42 ----
  // Desde la 1.0.43 los comprobantes viven en fiscal_documents (uno por factura o nota
  // de crédito). Estas columnas quedan solo para leer lo emitido antes; ya no se escriben.
  invoiceStatus        String    @default("NONE") @map("invoice_status") // NONE | PENDING | AUTHORIZED | REJECTED
  invoiceType          String?   @map("invoice_type")  // FACTURA_A | FACTURA_B | FACTURA_C | NC_A | NC_B | NC_C
  invoiceCbteTipo      Int?      @map("invoice_cbte_tipo") // Código de ARCA: 1=FacA, 6=FacB, 11=FacC...
  invoicePointOfSale   Int?      @map("invoice_point_of_sale")
  invoiceNumber        Int?      @map("invoice_number")
  cae                  String?
  caeExpiresAt         DateTime? @map("cae_expires_at")
  invoiceDate          DateTime? @map("invoice_date")
  invoiceRequestedAt   DateTime? @map("invoice_requested_at")
  invoiceAttempts      Int       @default(0) @map("invoice_attempts")
  invoiceError         String?   @map("invoice_error")
  // Neto e IVA que se declararon: la factura A los imprime discriminados
  invoiceNeto          Float?    @map("invoice_neto")
  invoiceIva           Float?    @map("invoice_iva")
