  async findAll(params?: { sessionId?: string; userId?: string; from?: string; to?: string; paymentMethod?: string; limit?: number; search?: string; withCost?: string | boolean; clientId?: string; locality?: string }) {
    const where: any = {};
    // Historial: las ventas de un cliente, o de los clientes de una localidad (reparto)
    if (params?.clientId) where.clientId = params.clientId;
    else if (params?.locality) where.client = { locality: params.locality };
    if (params?.sessionId) where.sessionId = params.sessionId;
    if (params?.userId) where.userId = params.userId;
    if (params?.paymentMethod) where.paymentMethodSummary = params.paymentMethod;
    if (params?.from || params?.to) {
      where.createdAt = {};
      if (params.from) where.createdAt.gte = new Date(params.from);
      if (params.to) where.createdAt.lte = new Date(params.to);
    }
    if (params?.search) {
      const searchVal = params.search.trim().toLowerCase();
      if (/^\d+$/.test(searchVal)) {
        where.saleNumber = parseInt(searchVal);
      } else {
        where.items = {
          some: {
            productName: {
              contains: searchVal
            }
          }
        };
      }
    }
    try {
      const includeCost = params?.withCost === true || params?.withCost === 'true';
      const queryOptions: any = {
        where,
        include: {
          items: includeCost ? {
            include: {
              product: {
                select: {
                  costPrice: true
                }
              }
            }
          } : true,
          payments: true,
          user: { select: { fullName: true, username: true } },
          client: { select: { id: true, name: true, dni: true, cuit: true, ivaCondition: true, phone: true, address: true, locality: true } },
        },
        orderBy: { createdAt: 'desc' },
      };

      if (params?.limit && !isNaN(params.limit)) {
        queryOptions.take = params.limit;
      } else if (!params?.from && !params?.to) {
        queryOptions.take = 100;
      } else {
        // Safe upper bound for date ranges (prevents Node.js OOM if kiosk has 10,000+ sales)
        queryOptions.take = 2500;
      }

      return await this.prisma.sale.findMany(queryOptions);
    } catch (err) {
      console.error('Error in findAll sales:', err);
      return [];
    }
  }

