    for (const sale of sales) {
      for (const item of sale.items) {
        if (item.productId === 'VIRTUAL_LOAD_1' || item.product?.barcode === 'VIRTUAL1') {
          const amt = item.total;
          totalVirtual1 += amt;
          itemsList.push({
            id: sale.id,
            createdAt: sale.createdAt,
