        } else if (item.productId === 'VIRTUAL_LOAD_2' || item.product?.barcode === 'VIRTUAL2') {
          const amt = item.total;
          totalVirtual2 += amt;
          itemsList.push({
            id: sale.id,
            createdAt: sale.createdAt,
            type: 'Carga Virtual 2',
            amount: amt,
            quantity: item.quantity
          });
        }
      }
    }
    
