// apps/backend/src/modules/subscription/subscription.service.ts
  async freshStatus(): Promise<SubscriptionStatus> {
    const s = this.getStatus();
    if (!this.stored.deviceId || s.state === 'EXEMPT' || Date.now() - this.lastFreshTry < 60_000) return s;
    const age = s.lastSyncAt ? Date.now() - Date.parse(s.lastSyncAt) : Infinity;
    if (s.state === 'READ_ONLY' || s.state === 'GRACE') {
      this.lastFreshTry = Date.now();
      return this.refresh().catch(() => s);
    }
    if (age > 30 * 60_000) {
      this.lastFreshTry = Date.now();
      this.refresh().catch(() => {});
    }
    return s;
  }

// apps/backend/src/modules/subscription/subscription.controller.ts
storeSession(@Body() body: { legacyStoreId?: string; legacyIdToken?: string }) {
    // Demo pública: nunca una sesión de la cuenta. La app de la demo usa su Firebase local
    // (VENTRA_DEMO); cualquier otra se niega a seguir al ver demo: true (ver ventraFirebase.ts).
    if (process.env.DEMO_MODE === 'true') return { linked: false, demo: true };
    // La agenda de turnos también vive en la tienda (ventra_stores): necesita la misma sesión
    const { features } = this.subscription.getStatus();
    if (!features.tienda && !features.agenda) {
      throw new ForbiddenException({
        code: 'PLAN_NO_TIENDA',
        message: 'Tu plan Ventra Caja no incluye la tienda online. Pasate al plan Full en ventra.store para usarla.',
      });
    }
    try {
      const session = await this.subscription.storeSession({
        legacyStoreId: typeof body?.legacyStoreId === 'string' ? body.legacyStoreId : undefined,
        legacyIdToken: typeof body?.legacyIdToken === 'string' ? body.legacyIdToken : undefined,
      });
      return session ? { linked: true, ...session } : { linked: false };
    } catch {
      throw new ServiceUnavailableException('No se pudo conectar con la tienda online. Revisá internet y probá de nuevo.');
    }
  }

// apps/backend/src/modules/subscription/subscription.service.ts

  getStatus(): SubscriptionStatus {
    const pending = this.stored.pending && Date.parse(this.stored.pending.expiresAt) > Date.now()
      ? { code: this.stored.pending.code, url: `${ACCOUNT_URL}?code=${this.stored.pending.code}`, expiresAt: this.stored.pending.expiresAt }
      : null;

    const all = planFeatures(null);
    if (this.exempt) return { state: 'EXEMPT', enforced: false, features: all, pending };

    const license = this.stored.license && this.stored.signature ? this.verify(this.stored.license, this.stored.signature) : null;
    if (!license || license.deviceId !== this.stored.deviceId) {
      // Instalación nueva: hay que vincularla con la cuenta que pagó el plan
      if (this.stored.install?.kind === 'new') return { state: 'NEEDS_LINK', enforced: true, features: all, pending };
      return { state: 'UNLINKED', enforced: false, features: all, pending };
    }

    const linkedAt = new Date(this.stored.linkedAt || license.issuedAt);
    const { state, graceEnd, daysLeft } = computeState(license, linkedAt, this.effectiveNow(license));
    return {
      state,
      enforced: true,
      email: license.email,
      plan: license.plan,
      // La licencia viene firmada por Ventra: el plan no se puede cambiar desde la PC
      features: planFeatures(license.plan),
      planName: license.planName,
      rubro: license.rubro ?? null,
      paidUntil: license.paidUntil,
      graceEndsAt: graceEnd.toISOString(),
      daysLeft,
      lastSyncAt: license.issuedAt,
      pending,
    };
  }

